window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U1"]={"deck":"U1","slides":[{"p":1,"title":"표지: 01 전통과 진보의 시대, Arts and Craft","terms":["Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["1강이 시작돼요. 제목이 '전통과 진보의 시대'예요.","전통(옛 양식)과 진보(기계와 철)가 부딪히던 시대라는 뜻이에요.","이 강의의 도착점은 **미술공예운동(Arts and Crafts Movement)** 이에요."]},{"kind":"say","lines":["이 과목의 주문을 먼저 외워요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 → 새 장식 → 정리 → 없애.","1강은 그중 맨 앞, '싫어' 를 맡아요. 그 '싫어' 가 **미술공예운동(Arts and Crafts Movement)** 이에요."]}],"pass2":[],"pass3":[]},{"p":2,"title":"시대정신과 건축디자인, 계몽주의","terms":["계몽주의","산업혁명"],"pass1":[{"kind":"say","lines":["사람들이 똑똑해지면서 세상이 바뀐 이야기예요.","**계몽주의(Enlightenment)** 덕분에 왕과 교회 대신 시민이 주인공이 돼요.","그 시민들이 기계를 만들어 **산업혁명(Industrial Revolution)** 을 일으켜요."]},{"kind":"analogy","head":"반장이 바뀐 교실","scene":"옛날에는 선생님(왕과 교회)이 전부 정했는데, 어느 날 학생들이 '우리도 생각할 줄 안다' 고 말해요.","map":[["선생님이 다 정하던 교실","절대주의 시대"],["학생들이 스스로 정하기 시작","**계몽주의(Enlightenment)**"],["학생들이 만든 새 규칙","민주주의, 자유, 평등"]]}],"pass2":[{"kind":"points","head":"**계몽주의(Enlightenment)** 가 무엇인가요","items":["17세기에서 18세기로 넘어가는 시기에 등장했어요.","시민의식이 깨어나면서 교회와 국가의 절대주의가 쇠퇴했어요.","민주주의, 자유, 평등 같은 새로운 가치를 중요하게 여겼어요."]},{"kind":"points","head":"**계몽주의(Enlightenment)** 가 건축에 미친 영향","items":["시민계급의 형성을 촉진했어요. 봉건주의에서 풀려나 이성을 인간의 본질로 봤어요.","미국 독립(1776)과 프랑스 혁명(1789)으로 민주적 공화국이 세워졌어요.","시민계층과 중산층이 사회의 새 주체가 되어 기계를 발명하고 **산업혁명(Industrial Revolution)** 을 주도했어요.","그 결과로 현대건축이 발생해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**계몽주의(Enlightenment)** 가 등장한 시기는 언제일까요?","choices":["15세기","17세기에서 18세기로 넘어가는 시기","19세기 말"],"a":1,"why":"슬라이드에 17_18세기 전환기라고 적혀 있어요."},{"kind":"english","head":"논술 답안: 계몽주의와 건축","en":"계몽주의는 17세기에서 18세기 전환기에 등장하여 시민의식을 깨우고 절대주의를 쇠퇴시켰으며, 미국 독립(1776)과 프랑스 혁명(1789)을 거쳐 시민계층이 산업혁명을 주도하면서 현대건축이 발생하였다.","ko":"계몽주의 → 시민계급 → 산업혁명 → 현대건축 순서로 써요.","tip":"'1776 미국, 1789 프랑스' 두 연도만 붙잡으면 문장이 살아나요."}],"walk":{"head":null,"parts":[{"b":[0.039,0.05,0.31,0.05],"c":[0.0235,0.02,0.341,0.11],"r":4.1333,"img":"img/U1/walk/p002_22_01.jpg","say":"제목이 '시대정신과 건축디자인' 이에요. 시대가 바뀌면 건물도 바뀐다는 뜻이에요."},{"b":[0.05,0.17,0.64,0.29],"c":[0.018,0.154,0.704,0.322],"r":2.9151,"img":"img/U1/walk/p002_22_02.jpg","say":"위 덩어리는 **계몽주의(Enlightenment)** 가 언제, 무엇이었는지예요."},{"b":[0.05,0.56,0.92,0.33],"c":[0,0.5435,1,0.363],"r":3.6731,"img":"img/U1/walk/p002_22_03.jpg","say":"아래 덩어리는 그것이 건축까지 이어지는 길이에요. 연도 1776, 1789 를 꼭 봐요."}]}},{"p":3,"title":"산업혁명의 전개","terms":["산업혁명","농업혁명"],"pass1":[{"kind":"say","lines":["**산업혁명(Industrial Revolution)** 이 어떻게 시작됐는지 순서만 봐요.","농사가 잘돼서 남는 것이 생기고, 사람이 도시로 몰리고, 증기기관이 나와요.","중심지는 영국, 시기는 18세기 말부터 19세기 중반이에요."]},{"kind":"points","head":"한 줄로 묶기","items":["**농업혁명(Agricultural Revolution)** 이 먼저, **산업혁명(Industrial Revolution)** 이 나중이에요.","건축에는 '새 재료, 새 건물 종류' 두 가지 숙제가 생겨요."]}],"pass2":[{"kind":"points","head":"**농업혁명(Agricultural Revolution)** 부터 차례대로","items":["농업기술이 발달해 농장이 커지고 농산물 생산력이 늘었어요.","모직물 공업이 발달해 양 사육이 늘고, 일자리를 찾아 노동자가 도시로 들어왔어요.","남는 생산물을 나르려고 교통체계가 자리 잡았어요.","증기기관이 발명되어 석탄과 원료 수송이 쉽고 노동력이 많은 곳에 공장이 모였어요."]},{"kind":"points","head":"**산업혁명(Industrial Revolution)** 이 건축에 미친 영향","items":["생활 전반에 기계와 공업 기술을 받아들여 유리, 콘크리트 같은 재료를 대량생산했어요.","공업과 경제활동이 도시로 몰려 도시화와 집합주택이 등장했어요.","자본주의 경제가 발달해 관청, 은행, 사무소, 상업시설 같은 새 건축 과제가 생겼어요.","새로운 기능, 새로운 형태의 건축물이 필요해졌어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**산업혁명(Industrial Revolution)** 의 중심지와 시기로 맞는 것은?","choices":["프랑스, 17세기","영국, 18세기 말에서 19세기 중반","독일, 20세기 초"],"a":1,"why":"슬라이드에 영국 18세기 말부터 19세기 중반이라고 적혀 있어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**농업혁명(Agricultural Revolution)** 이 **산업혁명(Industrial Revolution)** 보다 먼저예요. 순서를 바꿔 묻는 문제가 나와요.","증기기관은 산업혁명의 원인이자 도구예요. 건축 재료가 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.037,0.05,0.22,0.05],"c":[0.025,0.02,0.244,0.11],"r":2.9576,"img":"img/U1/walk/p003_22_01.jpg","say":"제목 '산업혁명의 전개'."},{"b":[0.05,0.17,0.92,0.32],"c":[0,0.154,1,0.352],"r":3.7879,"img":"img/U1/walk/p003_22_02.jpg","say":"위 덩어리는 **산업혁명(Industrial Revolution)** 이 일어난 순서예요."},{"b":[0.05,0.56,0.86,0.29],"c":[0.007,0.544,0.946,0.322],"r":3.9172,"img":"img/U1/walk/p003_22_03.jpg","say":"아래 덩어리는 건축에 미친 영향 네 가지예요. 시험에 자주 나와요."}]}},{"p":4,"title":"철의 시대와 신건축운동","terms":["cast iron","wrought iron","steel","장스팬","만국박람회"],"pass1":[{"kind":"say","lines":["19세기의 새 재료는 철이에요. 여기에 철근 콘크리트가 더해져요.","철로 지으면 기둥이 가늘고 지붕이 넓고 실내가 밝아요.","이 세 가지가 이 쪽의 전부예요."]},{"kind":"analogy","head":"철 삼형제","scene":"같은 철인데 성격이 셋이에요. 형제로 외우면 안 헷갈려요.","map":[["딱딱한데 잘 부러지는 형","**주철(cast iron)**"],["잘 늘어나는 둘째","**단철(wrought iron)**"],["눌러도 당겨도 버티는 막내 천재","**철골(강철)(steel)**"]]}],"pass2":[{"kind":"points","head":"신건축운동이 나온 배경","items":["19세기에 철물과 철근 콘크리트라는 두 신재료, 신공법을 매개로 성립하고 발전했어요.","**주철(cast iron)**, **단철(wrought iron)**, **철골(강철)(steel)** 의 철물 건축이 주축이 됐어요.","완전한 신재료인 **철골(강철)(steel)** 은 1709년 발명됐어요.","공업 재료로 쓰이다가 1820년경 건축에 들어왔고, 1870년을 기점으로 사용량이 크게 늘었어요."]},{"kind":"points","head":"중심 국가 두 곳","items":["프랑스는 실험 정신으로 예술적 가능성을 탐구했어요.","영국은 전통적 실용 정신을 발휘했고, 식민지 점령과 활발한 무역으로 앞서 나갔어요."]},{"kind":"points","head":"철 건축의 장점","items":["기차역, **만국박람회(World Exposition)** 전시관, 박물관, 백화점, 아케이드, 교회, 온실 같은 새 건물 유형이 필요했어요.","이런 유형은 유럽 열강의 자존심이 걸려 경쟁이 치열했어요.","**장스팬(Long Span)**, 가는 기둥, 밝은 실내. 이 세 단어가 철물건축의 장점이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**철골(강철)(steel)** 이 발명된 해는 언제일까요?","choices":["1709년","1820년","1870년"],"a":0,"why":"1709년 발명, 1820년경 건축 도입, 1870년 사용량 급증이에요. 세 연도를 세트로 외워요."},{"kind":"check","q":"철물건축의 장점 세 가지로 맞는 것은?","choices":["두꺼운 벽, 작은 창, 어두운 실내","**장스팬(Long Span)**, 가는 기둥, 밝은 실내","돌 장식, 무거운 지붕, 좁은 공간"],"a":1,"why":"장스팬, 가는 기둥, 밝은 실내는 세트로 외우는 답이에요."},{"kind":"english","head":"논술 답안: 철의 시대","en":"19세기 신건축운동은 철물과 철근 콘크리트를 매개로 성립하였고, 주철, 단철, 철골의 철물건축이 주축이 되었으며, 장스팬과 가는 기둥과 밝은 실내로 기차역과 박람회 전시관과 백화점의 해결책이 되었다.","ko":"재료 → 장점 → 건물 유형 순서로 이어 써요.","tip":"'장, 가, 밝' 세 글자로 장스팬, 가는 기둥, 밝은 실내를 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.035,0.31,0.05],"c":[0.0145,0.005,0.341,0.11],"r":4.1333,"img":"img/U1/walk/p004_23_01.jpg","say":"제목 '철의 시대와 신건축운동'."},{"b":[0.04,0.115,0.92,0.28],"c":[0.0,0.099,1,0.312],"r":4.2735,"img":"img/U1/walk/p004_23_02.jpg","say":"출현 배경. 1709, 1820, 1870 세 연도를 봐요."},{"b":[0.04,0.44,0.75,0.16],"c":[0.0025,0.424,0.825,0.192],"r":5.7292,"img":"img/U1/walk/p004_23_03.jpg","say":"중심 국가. 프랑스는 실험, 영국은 실용이에요."},{"b":[0.04,0.67,0.92,0.22],"c":[0.0,0.654,1,0.252],"r":5.291,"img":"img/U1/walk/p004_23_04.jpg","say":"철 건축의 장점. 마지막 줄의 세 단어가 핵심이에요."}]}},{"p":5,"title":"유럽 열강의 박물관 건축 경쟁과 그랑 팔레","terms":["갤러리 형","그랑 팔레","만국박람회"],"pass1":[{"kind":"say","lines":["나라들이 박물관으로 힘자랑을 했다는 이야기예요.","그래서 가운데가 뻥 뚫린 **갤러리 형(Gallery Type)** 이 표준이 돼요.","아래 사진은 파리 **그랑 팔레(Grand Palais)**, 1900년이에요."]}],"pass2":[{"kind":"points","head":"박물관 건축 경쟁","items":["문화 인프라를 제공한다는 명분에, 제국의 국력을 과시하는 정치적 목적이 겹쳐 있었어요.","대형 전시공간의 표준형인 **갤러리 형(Gallery Type)** 이 등장했어요.","천장까지 뻥 뚫린 중앙 로비를 전시공간이 돌아가며 에워싸는 형식이에요.","중앙 로비에 자연 채광을 살리려고 천장을 철물과 유리로 덮었어요."]},{"kind":"points","head":"부르주아의 신건축 활용","items":["넓고 위생적인 실내 분위기를 자기들 이미지로 삼았어요.","철물과 유리를 백화점, 아케이드, **만국박람회(World Exposition)** 전시관에 적극 썼어요.","자본주의가 밝고 건강한 체제임을 증명하는 상징이었어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**갤러리 형(Gallery Type)** 의 특징으로 맞는 것은?","choices":["중앙 로비 없이 방이 줄지어 있다","천장까지 뚫린 중앙 로비를 전시공간이 에워싸고 천장을 철물과 유리로 덮는다","지하에 전시실을 모은다"],"a":1,"why":"중앙 로비 + 철과 유리 천장이 **갤러리 형(Gallery Type)** 의 두 조건이에요."},{"kind":"english","head":"논술 답안: 갤러리 형","en":"갤러리 형은 19세기 대형 전시공간의 표준형으로, 천장까지 뚫린 중앙의 큰 로비를 중심으로 전시공간이 에워싸는 형식이며, 중앙로비의 자연 채광을 위해 천장을 철물과 유리로 덮었다.","ko":"표준형이라는 말과 철물, 유리 천장을 꼭 넣어요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.92,0.33],"c":[0.0,0.0335,1,0.363],"r":3.6731,"img":"img/U1/walk/p005_22_01.jpg","say":"위 덩어리가 박물관 경쟁이에요. **갤러리 형(Gallery Type)** 설명을 찾아 읽어요."},{"b":[0.04,0.44,0.9,0.2],"c":[0,0.424,0.99,0.232],"r":5.6897,"img":"img/U1/walk/p005_22_02.jpg","say":"아래 덩어리가 부르주아의 활용이에요."},{"b":[0.06,0.66,0.37,0.3],"c":[0.0415,0.644,0.407,0.332],"r":1.6345,"img":"img/U1/walk/p005_22_03.jpg","say":"왼쪽 사진은 **그랑 팔레(Grand Palais)** 내부예요. 천장 전체가 철과 유리예요."},{"b":[0.44,0.66,0.54,0.3],"c":[0.406,0.644,0.594,0.332],"r":2.3855,"img":"img/U1/walk/p005_22_04.jpg","say":"오른쪽은 그 외관이에요. 유리 지붕이 길게 이어져요."},{"b":[0.55,0.965,0.2,0.03],"c":[0.538,0.89,0.224,0.11],"r":2.7152,"img":"img/U1/walk/p005_22_05.jpg","say":"캡션에 '파리 그랑 팔레, 1900' 이라고 적혀 있어요."}]}},{"p":6,"title":"그랑 팔레의 오늘, 패션쇼와 올림픽","terms":["그랑 팔레"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요.","1900년에 지은 파리 **그랑 팔레(Grand Palais)** 를 지금도 쓰고 있다는 이야기예요.","왼쪽은 2017년 샤넬 패션쇼, 오른쪽은 2017년 올림픽 펜싱 경기예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["두 사진 모두 천장이 철 뼈대와 유리로 된 큰 돔이에요.","기둥 없이 뻥 뚫린 넓은 바닥, 이것이 **장스팬(Long Span)** 의 힘이에요.","철과 유리로 만든 큰 공간은 전시, 패션쇼, 경기장까지 무엇이든 담을 수 있어요.","캡션 그대로 두 장 다 **그랑 팔레(Grand Palais)** 이고 2017년 사진이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.02,0.03,0.46,0.9],"c":[0,0,0.506,0.99],"r":0.6815,"img":"img/U1/walk/p006_21_01.jpg","say":"왼쪽. 유리 돔 아래에 로켓 모형을 세운 패션쇼예요. 실내가 아주 밝아요."},{"b":[0.5,0.03,0.48,0.9],"c":[0.472,0,0.528,0.99],"r":0.7111,"img":"img/U1/walk/p006_21_02.jpg","say":"오른쪽. 같은 돔 아래 펜싱 경기장이 들어가 있어요."},{"b":[0.13,0.93,0.27,0.03],"c":[0.1165,0.89,0.297,0.11],"r":3.6,"img":"img/U1/walk/p006_21_03.jpg","say":"왼쪽 캡션: 그랑 팔레에서의 샤넬 패션쇼, 2017."},{"b":[0.6,0.93,0.31,0.03],"c":[0.5845,0.89,0.341,0.11],"r":4.1333,"img":"img/U1/walk/p006_21_04.jpg","say":"오른쪽 캡션: 그랑 팔레에서의 올림픽 펜싱경기, 2017."}]}},{"p":7,"title":"철 건축 대표 사례 목록","terms":["갤러리 라파예트 백화점","쁘렝땅 백화점","Crystal Palace","조셉 팩스턴","에펠탑","그랑 팔레","팜 하우스","만국박람회"],"pass1":[{"kind":"say","lines":["이 쪽은 이름표 모음이에요. 작품과 설명을 짝지어 외우는 쪽이에요.","백화점, 온실, 역, 탑, 시장, 박람회장이 모두 철과 유리예요.","시험에 이름과 설계자, 도시를 바꿔 묻는 문제가 나와요."]}],"pass2":[{"kind":"points","head":"백화점 두 곳","items":["**갤러리 라파예트 백화점(Galeries Lafayette)**: 파리. 유리와 철물 골격으로 천장을 덮은 19세기 백화점 건축의 대표 아이콘이에요.","**쁘렝땅 백화점(Printemps)**: 파리. 천장 유리 돔을 스테인드글라스로 장식했어요. 19세기 산업 자본주의를 대표하는 새로운 장소예요."]},{"kind":"points","head":"탑과 전시관","items":["**수정궁(Crystal Palace)**: **조셉 팩스턴(Joseph Paxton)** 설계. 건물 전체를 유리만으로 시공했어요.","**에펠탑(Eiffel Tower)**: 구스타브 에펠 설계. 다리에서 쌓은 구조 실력으로 310미터 기록을 세웠어요.","**에펠탑(Eiffel Tower)** 은 아치 기술을 수직으로 올린 것이고, 기단, 몸통, 탑으로 구성된 철저한 기술 대중주의의 산물이에요.","**그랑 팔레(Grand Palais)**: 1900년 **만국박람회(World Exposition)** 장으로 건설했어요."]},{"kind":"points","head":"그 밖의 사례","items":["파리 중앙시장: 오스망의 도시계획(1854년부터)의 일부로 건설했어요.","**팜 하우스(Palm House)**: 런던 큐가든의 온실이에요.","패딩턴 역사: 런던이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"건물 전체를 유리만으로 시공한 **수정궁(Crystal Palace)** 의 설계자는 누구일까요?","choices":["구스타브 에펠","**조셉 팩스턴(Joseph Paxton)**","오스망"],"a":1,"why":"수정궁은 조셉 팩스턴, 에펠탑은 구스타브 에펠이에요. 이 짝을 바꿔 내는 문제가 많아요."},{"kind":"check","q":"**에펠탑(Eiffel Tower)** 의 높이는 얼마일까요?","choices":["210미터","310미터","410미터"],"a":1,"why":"슬라이드에 310미터라고 적혀 있어요."},{"kind":"warn","head":"헷갈리는 짝","items":["**갤러리 라파예트 백화점(Galeries Lafayette)** 과 **쁘렝땅 백화점(Printemps)** 은 둘 다 파리예요. 쁘렝땅 쪽만 스테인드글라스예요.","**팜 하우스(Palm House)** 는 런던 큐가든의 온실, 파리가 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.92,0.12],"c":[0,0,1,0.2045],"r":6.52,"img":"img/U1/walk/p007_23_01.jpg","say":"**갤러리 라파예트 백화점(Galeries Lafayette)**, 파리."},{"b":[0.05,0.2,0.92,0.11],"c":[0,0.1528,1,0.2045],"r":6.52,"img":"img/U1/walk/p007_23_02.jpg","say":"**쁘렝땅 백화점(Printemps)**, 파리. 스테인드글라스 유리 돔."},{"b":[0.05,0.35,0.92,0.05],"c":[0,0.2728,1,0.2045],"r":6.52,"img":"img/U1/walk/p007_23_03.jpg","say":"**수정궁(Crystal Palace)**, **조셉 팩스턴(Joseph Paxton)** 설계."},{"b":[0.05,0.44,0.92,0.16],"c":[0,0.4178,1,0.2045],"r":6.52,"img":"img/U1/walk/p007_23_04.jpg","say":"**에펠탑(Eiffel Tower)**, 310미터. 기단, 몸통, 탑."},{"b":[0.05,0.64,0.7,0.15],"c":[0.015,0.624,0.77,0.182],"r":5.641,"img":"img/U1/walk/p007_23_05.jpg","say":"파리 중앙시장과 **그랑 팔레(Grand Palais)**, 1900."},{"b":[0.05,0.81,0.45,0.13],"c":[0.0275,0.794,0.495,0.162],"r":4.0741,"img":"img/U1/walk/p007_23_06.jpg","say":"**팜 하우스(Palm House)** 와 패딩턴 역사, 둘 다 런던이에요."}]}},{"p":8,"title":"철 건축 사진 여섯 장","terms":["갤러리 라파예트 백화점","쁘렝땅 백화점","팜 하우스","에펠탑"],"pass1":[{"kind":"say","lines":["앞 쪽 목록을 사진으로 보는 쪽이에요.","여섯 장 모두 철 뼈대와 유리가 주인공이에요.","캡션에 적힌 이름과 사진을 짝지어 기억해요."]}],"pass2":[{"kind":"points","head":"여섯 장이 무엇인가요","items":["위 왼쪽: 파리 **갤러리 라파예트 백화점(Galeries Lafayette)** 외관이에요.","위 가운데: 같은 백화점 내부. 유리 돔 아래로 층층이 매장이 둘러싸요.","위 오른쪽: 파리 **쁘렝땅 백화점(Printemps)** 천정 돔. 스테인드글라스 색유리예요.","아래 왼쪽: 런던 큐가든의 **팜 하우스(Palm House)**, 곡면 유리 온실이에요.","아래 가운데: 런던 패딩턴역. 아치 철골이 지붕을 건너질러요.","아래 오른쪽: **에펠탑(Eiffel Tower)** 건설과정 네 장면이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.01,0.08,0.28,0.4],"c":[0,0.06,0.308,0.44],"r":0.9333,"img":"img/U1/walk/p008_21_01.jpg","say":"파리 **갤러리 라파예트 백화점(Galeries Lafayette)** 외관."},{"b":[0.36,0.06,0.28,0.44],"c":[0.346,0.038,0.308,0.484],"r":0.8485,"img":"img/U1/walk/p008_21_02.jpg","say":"같은 백화점 내부의 유리 돔."},{"b":[0.65,0.07,0.33,0.41],"c":[0.6335,0.0495,0.363,0.451],"r":1.0732,"img":"img/U1/walk/p008_21_03.jpg","say":"파리 **쁘렝땅 백화점(Printemps)** 천정 돔, 스테인드글라스."},{"b":[0.01,0.58,0.32,0.38],"c":[0,0.561,0.352,0.418],"r":1.1228,"img":"img/U1/walk/p008_21_04.jpg","say":"런던 큐가든의 **팜 하우스(Palm House)** 온실."},{"b":[0.36,0.58,0.28,0.33],"c":[0.346,0.5635,0.308,0.363],"r":1.1313,"img":"img/U1/walk/p008_21_05.jpg","say":"런던 패딩턴역의 아치 철골 지붕."},{"b":[0.66,0.58,0.31,0.33],"c":[0.6445,0.5635,0.341,0.363],"r":1.2525,"img":"img/U1/walk/p008_21_06.jpg","say":"**에펠탑(Eiffel Tower)** 이 조금씩 올라가는 건설과정."}]}},{"p":9,"title":"만국박람회로 드러난 경쟁구도","terms":["만국박람회","대박람회","에펠탑","Crystal Palace","프리패브"],"pass1":[{"kind":"say","lines":["**만국박람회(World Exposition)** 는 나라 자랑 대회예요.","건물은 어차피 곧 부술 것이라 마음껏 실험할 수 있었어요.","그래서 빨리 조립하고 빨리 뜯는 방법, 즉 **프리패브(Prefabrication)** 가 자라나요."]},{"kind":"points","head":"연도 순서만 먼저","items":["1851 런던 → 1855, 1867 파리 → 1889 파리.","1851년 런던이 **대박람회(Great Exhibition)**, 1889년 파리가 **에펠탑(Eiffel Tower)** 이에요."]}],"pass2":[{"kind":"points","head":"**만국박람회(World Exposition)** 가 왜 건축 경쟁이 되었나요","items":["새로운 공산품을 전시하는 행사이면서 19세기 국가 간 산업화 경쟁의 장이었어요.","일반 대중을 상대로 열리는 축제 성격이었어요.","한 번 열릴 때마다 십 수 채의 건물을 새로 지어야 했어요.","대부분 일회용이라 새로운 건축적 실험의 부담이 적었어요."]},{"kind":"points","head":"연도와 나라","items":["1851년 런던 **만국박람회(World Exposition)** 를 대성공으로 이끈 영국. 이 박람회를 **대박람회(Great Exhibition)** 라 불러요.","파리는 1855년과 1867년 연달아 **만국박람회(World Exposition)** 를 열었어요.","프랑스 대혁명 100주년을 기념한 1889년 파리박람회에서 에펠이 **에펠탑(Eiffel Tower)** 을 남기며 **수정궁(Crystal Palace)** 을 능가하는 큰 획을 그었어요."]},{"kind":"points","head":"박람회 건축의 혁신성","items":["전시관에 알맞은 형태를 찾았어요. 신속하고 간단하게 조립, 해체할 수 있는 재료와 공법을 시도했어요.","규격화된 부재를 써서 현장에서 조립했어요. 이것이 오늘날 **프리패브(Prefabrication)** 의 출발점이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1851년 런던 **만국박람회(World Exposition)** 를 부르는 다른 이름은 무엇일까요?","choices":["**대박람회(Great Exhibition)**","세계박람회","파리박람회"],"a":0,"why":"영국이 대성공으로 이끌어 대박람회라고 불러요."},{"kind":"check","q":"1889년 파리박람회는 무엇을 기념한 것일까요?","choices":["영국 산업혁명 100주년","프랑스 대혁명 100주년","미국 독립 100주년"],"a":1,"why":"프랑스 대혁명(1789) 100주년이라 1889년이에요. 100을 더하면 됩니다."},{"kind":"english","head":"논술 답안: 만국박람회 건축","en":"만국박람회는 19세기 국가 간 산업화 경쟁의 장으로, 대부분 일회용 건물이어서 건축적 실험의 부담이 적었고, 신속하게 조립하고 해체할 수 있는 재료와 규격화된 부재의 현장 조립 공법을 발전시켜 프리패브의 출발점이 되었다.","ko":"경쟁, 일회용, 규격 부재 조립 세 마디를 넣어요.","tip":"'1789 + 100 = 1889' 로 에펠탑 해를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.8,0.09],"c":[0,0.0161,0.88,0.1778],"r":6.5992,"img":"img/U1/walk/p009_23_01.jpg","say":"제목 줄. 박람회가 곧 경쟁구도라는 말이에요."},{"b":[0.05,0.17,0.75,0.24],"c":[0.0125,0.154,0.825,0.272],"r":4.0441,"img":"img/U1/walk/p009_23_02.jpg","say":"축제, 십 수 채, 일회용. 실험이 쉬웠던 이유 세 가지예요."},{"b":[0.05,0.42,0.92,0.22],"c":[0,0.404,1,0.252],"r":5.291,"img":"img/U1/walk/p009_23_03.jpg","say":"1851, 1855, 1867, 1889. 연도 줄이에요."},{"b":[0.05,0.7,0.92,0.2],"c":[0,0.684,1,0.232],"r":5.7471,"img":"img/U1/walk/p009_23_04.jpg","say":"혁신성. 조립과 해체, 규격 부재 현장 조립이 **프리패브(Prefabrication)** 예요."}]}},{"p":10,"title":"조셉 팩스턴, 런던 만국박람회 수정궁, 1851","terms":["Crystal Palace","조셉 팩스턴","만국박람회","프리패브"],"pass1":[{"kind":"say","lines":["이 쪽의 주인공은 **수정궁(Crystal Palace)** 한 채예요.","1851년 런던 **만국박람회(World Exposition)** 전시관이고, 설계자는 **조셉 팩스턴(Joseph Paxton)** 이에요.","유리와 철로만 지은 거대한 온실이라고 생각하면 돼요."]},{"kind":"analogy","head":"정원사가 지은 거대한 온실","scene":"**조셉 팩스턴(Joseph Paxton)** 은 건축가가 아니라 온실을 짓던 정원사였어요.","map":[["온실 유리 한 장","규격화된 유리판"],["온실 쇠 뼈대","**주철(cast iron)** 부재"],["아주 커진 온실","**수정궁(Crystal Palace)**"]]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["벽이 돌이나 벽돌이 아니라 전부 유리예요. 건물 전체를 유리만으로 시공했어요.","같은 모양 부재가 계속 반복돼요. 규격 부재를 현장에서 조립한 **프리패브(Prefabrication)** 예요.","위쪽 스케치에 '속이 빈 기둥은 홈통 역할도 한다' 는 설명이 적혀 있어요.","위쪽 설명 글에 '우아하고 매우 경제적이며 구조적으로는 단순하고 정적' 이라고 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**수정궁(Crystal Palace)** 이 지어진 해와 도시는?","choices":["1851년 런던","1889년 파리","1900년 파리"],"a":0,"why":"1851년 런던 대박람회 전시관이에요."},{"kind":"english","head":"논술 답안: 수정궁","en":"수정궁은 1851년 런던 만국박람회 전시관으로 조셉 팩스턴이 설계하였고, 건물 전체를 유리만으로 시공하였으며, 규격화된 철물 부재를 현장에서 조립하여 프리패브 공법의 출발점이 되었다.","ko":"설계자, 연도, 도시, 공법 네 가지를 한 문장에 넣어요.","tip":"'팩스턴은 정원사, 그래서 유리 온실' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.13,0.08,0.72,0.4],"c":[0.094,0.06,0.792,0.44],"r":2.4,"img":"img/U1/walk/p010_21_01.jpg","say":"위쪽은 **조셉 팩스턴(Joseph Paxton)** 이 그린 초기 스케치와 단면이에요."},{"b":[0.14,0.49,0.72,0.42],"c":[0.104,0.469,0.792,0.462],"r":2.2857,"img":"img/U1/walk/p010_21_02.jpg","say":"아래 그림이 완성된 **수정궁(Crystal Palace)** 이에요. 옆으로 아주 길어요."},{"b":[0.6,0.92,0.38,0.05],"c":[0.581,0.89,0.418,0.11],"r":5.0667,"img":"img/U1/walk/p010_21_03.jpg","say":"캡션: 조셉 팩스턴, 런던 만국박람회 수정궁, 1851."}]}},{"p":11,"title":"1889년 파리 만국박람회, 기계관과 에펠탑 기초","terms":["만국박람회","기계관","에펠탑","Crystal Palace"],"pass1":[{"kind":"say","lines":["글자 없이 손 스케치만 있는 쪽이에요.","1889년 파리 **만국박람회(World Exposition)** 의 배치와 **기계관(Machinery Hall)** 을 그린 그림이에요.","**에펠탑(Eiffel Tower)** 의 다리 아래에서 **기계관(Machinery Hall)** 을 바라본 장면이에요."]}],"pass2":[{"kind":"points","head":"스케치에 적힌 글 그대로","items":["위 배치도에 센 강, **에펠탑(Eiffel Tower)**, **기계관(Machinery Hall)** 이 표시돼 있어요.","배치도 왼쪽에는 1878년 엑스포 때 만들어진 파빌리온이 있어요.","가운데 큰 그림은 **에펠탑(Eiffel Tower)** 의 기초부이고, 그 사이로 **기계관(Machinery Hall)** 외면이 보여요.","아래 그림 설명: **기계관(Machinery Hall)** 은 **수정궁(Crystal Palace)** 보다 구조적으로 훨씬 강하고 커요.","또 건물의 확장이 가능하도록 힌지 이음새를 썼고, 규모가 굉장히 크다고 적혀 있어요.","오른쪽 아래 작은 그림은 1873년 비엔나 전람회의 고전적 장식을 한 철제 큐폴라예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1889년 파리박람회의 **기계관(Machinery Hall)** 에 대한 설명으로 맞는 것은?","choices":["수정궁보다 작고 약했다","수정궁보다 구조적으로 훨씬 강하고 컸다","돌로 지었다"],"a":1,"why":"스케치에 그렇게 적혀 있어요. 확장이 가능하도록 힌지 이음새도 썼어요."}],"walk":{"head":null,"parts":[{"b":[0.34,0.02,0.64,0.2],"c":[0.296,0.004,0.704,0.232],"r":4.046,"img":"img/U1/walk/p011_21_01.jpg","say":"위 배치도. 센 강, 에펠탑, **기계관(Machinery Hall)** 의 자리를 봐요."},{"b":[0.15,0.2,0.5,0.48],"c":[0.125,0.176,0.55,0.528],"r":1.3889,"img":"img/U1/walk/p011_21_02.jpg","say":"**에펠탑(Eiffel Tower)** 기초부의 큰 아치. 사람과 견주면 크기가 실감 나요."},{"b":[0.13,0.68,0.48,0.31],"c":[0.106,0.658,0.528,0.342],"r":2.0585,"img":"img/U1/walk/p011_21_03.jpg","say":"**기계관(Machinery Hall)** 내부. 수정궁보다 강하고 크다고 적혀 있어요."},{"b":[0.55,0.85,0.22,0.12],"c":[0.538,0.834,0.244,0.152],"r":2.1404,"img":"img/U1/walk/p011_21_04.jpg","say":"힌지 이음새 설명. 건물을 늘릴 수 있게 만든 장치예요."}]}},{"p":12,"title":"밀라노의 갈레리아 비토리오 엠마누엘레","terms":["장스팬"],"pass1":[{"kind":"say","lines":["사진 세 장짜리 쪽이에요.","밀라노의 갈레리아 비토리오 엠마누엘레예요.","돌로 지은 옛 건물 사이의 길에 철과 유리 지붕을 덮은 아케이드예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["바깥은 돌로 만든 고전 양식 벽과 큰 아치 입구예요.","그 아치 안쪽으로 철 뼈대와 유리로 된 둥근 천장이 보여요.","가운데 교차부에는 유리 돔이 얹혀 있어요.","옛 양식의 벽 + 새 재료의 지붕. 이 조합이 19세기 아케이드의 모습이에요.","기둥을 거의 세우지 않고 길 위를 건너지른 것이 **장스팬(Long Span)** 의 힘이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.02,0.64,0.48],"c":[0,0,0.704,0.528],"r":1.7778,"img":"img/U1/walk/p012_21_01.jpg","say":"위 사진. 광장에서 본 입구. 돌 벽에 큰 아치가 뚫려 있어요."},{"b":[0.3,0.1,0.12,0.14],"c":[0.26,0.084,0.2,0.172],"r":1.5504,"img":"img/U1/walk/p012_21_02.jpg","say":"아치 안쪽으로 철과 유리 지붕이 살짝 보여요."},{"b":[0.1,0.54,0.42,0.44],"c":[0.079,0.516,0.462,0.484],"r":1.2727,"img":"img/U1/walk/p012_21_03.jpg","say":"아래 왼쪽. 아케이드 통로 전체를 덮은 유리 볼트 지붕이에요."},{"b":[0.54,0.54,0.44,0.44],"c":[0.516,0.516,0.484,0.484],"r":1.3333,"img":"img/U1/walk/p012_21_04.jpg","say":"아래 오른쪽. 교차부 위의 유리 돔을 올려다본 사진이에요."},{"b":[0.02,0.5,0.32,0.03],"c":[0.004,0.46,0.352,0.11],"r":4.2667,"img":"img/U1/walk/p012_21_05.jpg","say":"캡션: 밀라노의 갈레리아 비토리오 엠마누엘레."}]}},{"p":13,"title":"빈의 팔멘하우스","terms":["팜 하우스"],"pass1":[{"kind":"say","lines":["사진 네 장짜리 쪽이에요. 빈의 팔멘하우스예요.","팔멘하우스는 야자나무 온실이라는 뜻이에요.","런던 큐가든의 **팜 하우스(Palm House)** 와 같은 종류의 건물이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["초록색으로 칠한 철 뼈대가 그대로 드러나 있어요.","지붕이 곡면이에요. 철은 휘어서 만들 수 있으니 이런 모양이 나와요.","벽이 거의 전부 유리라서 안이 아주 밝아요. 식물을 기르려면 빛이 필요해요.","아래 왼쪽 사진만 돌 기둥과 사자 조각이 있어요. 옛 양식 장식이 함께 남아 있어요.","런던 큐가든의 **팜 하우스(Palm House)** 와 견주어 보면 온실 건축의 공통점이 보여요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.83,0.02,0.15,0.04],"c":[0.8,0,0.2,0.11],"r":2.4242,"img":"img/U1/walk/p013_21_01.jpg","say":"오른쪽 위에 '빈의 팔멘하우스' 라고 적혀 있어요."},{"b":[0.02,0.06,0.46,0.44],"c":[0,0.038,0.506,0.484],"r":1.3939,"img":"img/U1/walk/p013_21_02.jpg","say":"왼쪽 위. 가는 철 부재로 나눈 유리 벽이에요."},{"b":[0.5,0.06,0.48,0.44],"c":[0.472,0.038,0.528,0.484],"r":1.4545,"img":"img/U1/walk/p013_21_03.jpg","say":"오른쪽 위. 곡면 유리 지붕이 이어지는 전체 모습이에요."},{"b":[0.02,0.52,0.46,0.46],"c":[0,0.494,0.506,0.506],"r":1.3333,"img":"img/U1/walk/p013_21_04.jpg","say":"왼쪽 아래. 돌 기둥과 사자 조각 장식이 함께 있어요."},{"b":[0.5,0.52,0.48,0.46],"c":[0.472,0.494,0.528,0.506],"r":1.3913,"img":"img/U1/walk/p013_21_05.jpg","say":"오른쪽 아래. 휘어 올라간 철 뼈대를 가까이서 본 모습이에요."}]}},{"p":14,"title":"파리의 생 주느비에브 도서관과 국립도서관","terms":["cast iron","장스팬"],"pass1":[{"kind":"say","lines":["사진 두 장짜리 쪽이에요. 파리의 도서관 두 곳이에요.","왼쪽 위는 생 주느비에브 도서관, 오른쪽 아래는 파리 국립도서관이에요.","둘 다 열람실 천장을 철로 만든 점이 같아요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["생 주느비에브 도서관은 가운데에 가는 **주철(cast iron)** 기둥이 한 줄로 서 있어요.","그 기둥에서 철제 아치가 좌우로 뻗어 두 줄의 배럴 볼트 천장을 받쳐요.","아치에는 구멍이 뚫린 장식 무늬가 들어가 있어요. 철이라 이런 무늬를 뽑을 수 있어요.","국립도서관 열람실은 가는 기둥이 여러 개의 얕은 돔을 받치고, 돔 가운데에 채광창이 뚫려 있어요.","두 곳 다 두꺼운 벽 대신 가는 기둥으로 넓은 방을 만든 **장스팬(Long Span)** 의 사례예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"헷갈리는 짝","items":["생 주느비에브 도서관은 철 아치 두 줄, 국립도서관은 얕은 돔 여러 개예요.","둘 다 파리예요. 도시를 바꿔 묻는 문제에 속지 마세요."]}],"walk":{"head":null,"parts":[{"b":[0.01,0.03,0.59,0.53],"c":[0,0.0035,0.649,0.583],"r":1.4843,"img":"img/U1/walk/p014_21_01.jpg","say":"왼쪽 위 사진이 생 주느비에브 도서관 열람실이에요."},{"b":[0.28,0.06,0.06,0.38],"c":[0.21,0.041,0.2,0.418],"r":0.638,"img":"img/U1/walk/p014_21_02.jpg","say":"가운데 세로로 선 가는 **주철(cast iron)** 기둥 한 줄을 봐요."},{"b":[0.02,0.56,0.24,0.03],"c":[0.008,0.52,0.264,0.11],"r":3.2,"img":"img/U1/walk/p014_21_03.jpg","say":"캡션: 파리의 생 주느비에브 도서관."},{"b":[0.42,0.43,0.56,0.55],"c":[0.384,0.395,0.616,0.605],"r":1.3576,"img":"img/U1/walk/p014_21_04.jpg","say":"오른쪽 아래 사진이 파리 국립도서관 열람실이에요."},{"b":[0.84,0.37,0.14,0.03],"c":[0.8,0.33,0.2,0.11],"r":2.4242,"img":"img/U1/walk/p014_21_05.jpg","say":"라벨: 파리 국립도서관."}]}},{"p":15,"title":"19세기 말 도시설계이론과 전원주택론","terms":["Garden City","에베네저 하워드"],"pass1":[{"kind":"say","lines":["이제 건물에서 도시로 이야기가 넘어가요.","도시가 너무 빽빽하고 집이 모자라서 새 계획 방법이 필요했어요.","그 답이 다음 쪽의 **전원도시(Garden City)** 예요."]},{"kind":"points","head":"이 쪽의 두 덩어리","items":["위: 왜 새 방법론이 필요했나(배경).","아래: 20세기 초 주거환경계획이 무엇을 노렸나(주안점)."]}],"pass2":[{"kind":"points","head":"새 방법론이 나온 배경","items":["도시인구가 계속 늘고, 도시가 과밀해지고, 비효율적이 되고, 주택가격이 올랐어요.","핵가족화가 빨라지면서 주택부족 문제가 커졌어요.","대도시 주거환경이 황폐해졌어요."]},{"kind":"points","head":"20세기 초 주거환경계획의 주안점","items":["외부환경은 공간적 여유를 두는 것이에요.","내부환경은 충분한 채광과 통풍이 가능하도록 개방적 성격을 주는 것이에요.","**에베네저 하워드(Ebenezer Howard)** 의 **전원도시(Garden City)** 개념과, 실천적 행동가 언윈의 영향을 받았어요.","각 단위주택에 독립된 외부공간을 주고, 자연과의 접촉을 늘리고, 공공시설을 충분히 마련해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"20세기 초 주거환경계획에서 내부환경의 주안점은 무엇일까요?","choices":["장식을 많이 넣는 것","충분한 채광과 통풍이 가능한 개방적 성격","방을 최대한 많이 만드는 것"],"a":1,"why":"밖은 공간적 여유, 안은 채광과 통풍. 이 두 줄로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.045,0.49,0.05],"c":[0.0105,0.015,0.539,0.11],"r":6.5333,"img":"img/U1/walk/p015_22_01.jpg","say":"제목 '19세기 말 도시설계이론과 전원주택론'."},{"b":[0.06,0.17,0.78,0.22],"c":[0.021,0.154,0.858,0.252],"r":4.5397,"img":"img/U1/walk/p015_22_02.jpg","say":"배경 세 줄. 과밀, 주택부족, 황폐화예요."},{"b":[0.06,0.45,0.85,0.42],"c":[0.0175,0.429,0.935,0.462],"r":2.6984,"img":"img/U1/walk/p015_22_03.jpg","say":"주안점. 밖은 여유, 안은 빛과 바람이 핵심이에요."}]}},{"p":16,"title":"전원도시(Garden City) 이론과 에베네저 하워드","terms":["Garden City","에베네저 하워드","Tomorrow","산업혁명"],"pass1":[{"kind":"say","lines":["**전원도시(Garden City)** 는 시골과 도시를 섞은 작은 자족도시예요.","제안한 사람은 **에베네저 하워드(Ebenezer Howard)**, 책 이름은 **내일(Tomorrow)** 이에요.","책이 나온 해는 1898년, 적정 인구는 32,000명이에요."]},{"kind":"analogy","head":"도시와 시골의 결혼","scene":"도시는 일자리는 많은데 답답하고, 시골은 한가한데 일자리가 없어요. 둘의 좋은 점만 모은 새 도시를 만들자는 생각이에요.","map":[["도시의 일자리와 시설","자족적인 경제"],["시골의 빛과 공기","저밀도 주거"],["둘을 합친 새 도시","**전원도시(Garden City)**"]]}],"pass2":[{"kind":"points","head":"**에베네저 하워드(Ebenezer Howard)** 와 책","items":["**에베네저 하워드(Ebenezer Howard)** 는 1850년에 태어나 1928년에 세상을 떠났어요.","저서 **내일(Tomorrow)** (1898)에서 최적인구 32,000명을 제시했어요.","**산업혁명(Industrial Revolution)** 이후의 비계획적인 도시 성장이 과밀화, 비효율성, 주택가격 상승을 낳았기 때문이에요."]},{"kind":"points","head":"**전원도시(Garden City)** 가 어떤 도시인가요","items":["위성도시가 아니라 자체적 독립성을 지닌 소규모 도시예요.","넓은 공간, 충분한 빛, 쾌적한 공기를 확보해 줄 수 있는 저밀도의 도시예요.","대도시와 지리적으로 떨어진 곳에 전원과 도시의 성격을 함께 지니는 자족적인 도시를 세우려 했어요.","경제적 자족도시이면서 사회주의 공동체의 이념을 담고 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**에베네저 하워드(Ebenezer Howard)** 가 저서 **내일(Tomorrow)** 에서 제시한 최적인구는?","choices":["8,000명","32,000명","58,000명"],"a":1,"why":"32,000명이에요. 58,000명은 가운데 중심도시의 인구라서 헷갈리기 쉬워요."},{"kind":"warn","head":"연도와 숫자 조심","items":["**내일(Tomorrow)** 은 1898년, 최초의 **전원도시(Garden City)** 레치워스는 1905년이에요.","32,000명은 전원도시 하나, 58,000명은 중심도시예요."]},{"kind":"english","head":"논술 답안: 전원도시 이론","en":"전원도시는 에베네저 하워드가 1898년 저서 내일에서 제시한 개념으로, 최적인구 32,000명의 자족적이고 저밀도인 소규모 도시이며, 대도시와 지리적으로 분리되어 전원과 도시의 성격을 동시에 지니고 경제적 자족과 사회주의 공동체의 이념을 담고 있다.","ko":"제안자, 연도, 책 이름, 인구, 자족과 저밀도를 모두 넣어요.","tip":"'1898 내일, 32,000명' 을 한 덩어리로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.11,0.39,0.06],"c":[0.0105,0.085,0.429,0.11],"r":5.2,"img":"img/U1/walk/p016_22_01.jpg","say":"제목 '전원도시 (Garden City) 이론'."},{"b":[0.03,0.25,0.5,0.12],"c":[0.005,0.234,0.55,0.152],"r":4.8246,"img":"img/U1/walk/p016_22_02.jpg","say":"**산업혁명(Industrial Revolution)** 이후의 문제 세 가지예요."},{"b":[0.06,0.42,0.47,0.06],"c":[0.0365,0.395,0.517,0.11],"r":6.2667,"img":"img/U1/walk/p016_22_03.jpg","say":"**에베네저 하워드(Ebenezer Howard)**, 1850년에서 1928년."},{"b":[0.08,0.5,0.75,0.4],"c":[0.0425,0.48,0.825,0.44],"r":2.5,"img":"img/U1/walk/p016_22_04.jpg","say":"책 **내일(Tomorrow)** 1898, 인구 32,000명, 자족, 저밀도."},{"b":[0.64,0.01,0.35,0.68],"c":[0.615,0,0.385,0.748],"r":0.6863,"img":"img/U1/walk/p016_22_05.jpg","say":"오른쪽은 하워드가 그린 다이어그램이에요. 도시들이 철도로 이어져요."}]}},{"p":17,"title":"영국 전원도시의 모형","terms":["Garden City","에베네저 하워드"],"pass1":[{"kind":"say","lines":["앞 쪽의 **전원도시(Garden City)** 를 그림으로 보는 쪽이에요.","가운데 큰 도시 하나를 작은 도시 여섯이 동그랗게 둘러싸요.","바깥은 농지로 막아서 도시가 더 커지지 못하게 해요."]},{"kind":"analogy","head":"도넛 하나와 그 둘레","scene":"한가운데 중앙공원이 있고, 거기서 도로가 바퀴살처럼 뻗어 나가요.","map":[["도넛 한가운데 구멍","중앙공원"],["바퀴살 도로","방사선으로 뻗은 길"],["도넛 바깥 테두리","경작지와 농원"]]}],"pass2":[{"kind":"points","head":"**전원도시(Garden City)** 모형의 규칙","items":["**전원도시(Garden City)** 외곽에 농업용 토지를 배치해 도시의 물리적 확장을 제한해요.","인구 5만 8천 명의 중심도시를 인구 32,000명의 작은 도시 6개가 원형으로 둘러싸요.","중심도시와 **전원도시(Garden City)** 는 철도와 도로로 연결해요.","중심부에는 중앙공원을 두고, 이 공원에서 방사선으로 뻗은 도로와 도넛 형태의 가로수길을 따라 주택과 정원이 들어서요.","그리고 외곽에는 경작지와 농원을 배치해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**전원도시(Garden City)** 모형에서 중심도시의 인구는 얼마일까요?","choices":["32,000명","5만 8천 명","10만 명"],"a":1,"why":"작은 전원도시 하나가 32,000명, 가운데 중심도시가 5만 8천 명이에요."},{"kind":"warn","head":"숫자 헷갈림 주의","items":["**에베네저 하워드(Ebenezer Howard)** 가 책에서 말한 32,000명은 **전원도시(Garden City)** 하나의 인구예요.","5만 8천 명은 그 여섯 도시가 둘러싸는 중심도시의 인구예요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.09,0.25,0.05],"c":[0.0375,0.06,0.275,0.11],"r":3.3333,"img":"img/U1/walk/p017_21_01.jpg","say":"제목 '영국 전원도시의 모형'."},{"b":[0.06,0.15,0.44,0.12],"c":[0.038,0.134,0.484,0.152],"r":4.2456,"img":"img/U1/walk/p017_21_02.jpg","say":"외곽 농지로 확장을 막는다는 규칙이에요."},{"b":[0.06,0.3,0.44,0.35],"c":[0.038,0.2825,0.484,0.385],"r":1.6762,"img":"img/U1/walk/p017_21_03.jpg","say":"5만 8천 명 중심도시 + 3만 2천 명 도시 6개, 그리고 철도와 도로 연결이에요."},{"b":[0.06,0.68,0.44,0.28],"c":[0.038,0.664,0.484,0.312],"r":2.0684,"img":"img/U1/walk/p017_21_04.jpg","say":"중앙공원, 방사선 도로, 도넛 가로수길, 바깥 경작지."},{"b":[0.5,0.18,0.49,0.62],"c":[0.461,0.149,0.539,0.682],"r":1.0538,"img":"img/U1/walk/p017_21_05.jpg","say":"오른쪽 그림이 Ward and Centre 다이어그램이에요. 가운데 공원에서 길이 뻗어요."}]}},{"p":18,"title":"최초의 전원도시 레치워스, 1905","terms":["Letchworth","언윈과 파커","보차분리","Garden City"],"pass1":[{"kind":"say","lines":["이론이 실제로 지어진 쪽이에요.","1905년 영국 헤트포드셔에 최초의 **전원도시(Garden City)** **레치워스(Letchworth)** 가 세워져요.","설계는 **언윈과 파커(Unwin and Parker)** 예요. 하워드가 아니라는 점이 시험 포인트예요."]}],"pass2":[{"kind":"points","head":"**레치워스(Letchworth)** 의 계획 내용","items":["1905년 영국 헤트포드셔에 최초의 **전원도시(Garden City)** 로 건설했어요.","레이먼드 언윈과 베리 파커, 즉 **언윈과 파커(Unwin and Parker)** 가 설계했어요.","정원을 가진 독립주택을 지어 주택마다 충분한 빛과 공기를 주었어요.","적절한 공용공간과 공원을 설치했어요.","도시의 과밀화와 필요 이상의 토지소비를 억제했어요.","보행자 우선의 도로와 엄격한 **보차분리(Pedestrian and Vehicle Separation)** 를 적용했어요."]},{"kind":"points","head":"**보차분리(Pedestrian and Vehicle Separation)** 가 무엇인가요","items":["사람이 걷는 길과 차가 다니는 길을 아예 갈라놓는 계획 기법이에요.","아이가 뛰어놀아도 차와 만나지 않게 하는 것이 목표예요.","**레치워스(Letchworth)** 에서 엄격하게 적용했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"최초의 **전원도시(Garden City)** **레치워스(Letchworth)** 를 설계한 사람은 누구일까요?","choices":["에베네저 하워드","**언윈과 파커(Unwin and Parker)**","필립 웹"],"a":1,"why":"이론은 하워드, 설계는 언윈과 파커예요. 가장 자주 나오는 함정이에요."},{"kind":"english","head":"논술 답안: 레치워스","en":"레치워스는 1905년 영국 헤트포드셔에 건설된 최초의 전원도시로, 레이먼드 언윈과 베리 파커가 설계하였으며, 정원을 가진 독립주택과 공용공간, 보행자 우선 도로와 엄격한 보차분리를 특징으로 한다.","ko":"연도, 나라, 설계자, 특징 순서로 써요.","tip":"'하워드는 책, 언윈과 파커는 땅' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.035,0.83,0.05],"c":[0,0,0.913,0.1845],"r":6.598,"img":"img/U1/walk/p018_22_01.jpg","say":"맨 윗줄에 1905년, 헤트포드셔, **레치워스(Letchworth)** 가 다 들어 있어요."},{"b":[0.09,0.09,0.66,0.06],"c":[0.057,0.0467,0.726,0.1467],"r":6.5985,"img":"img/U1/walk/p018_22_02.jpg","say":"설계자 줄. 레이먼드 언윈과 베리 파커예요."},{"b":[0.09,0.15,0.62,0.22],"c":[0.059,0.134,0.682,0.252],"r":3.6085,"img":"img/U1/walk/p018_22_03.jpg","say":"계획 내용 네 줄. 마지막 줄이 **보차분리(Pedestrian and Vehicle Separation)** 예요."},{"b":[0.09,0.42,0.44,0.55],"c":[0.068,0.3925,0.484,0.605],"r":1.0667,"img":"img/U1/walk/p018_22_04.jpg","say":"왼쪽 항공사진. 길이 구불구불하고 가운데에 녹지가 있어요."},{"b":[0.56,0.59,0.38,0.38],"c":[0.541,0.571,0.418,0.418],"r":1.3333,"img":"img/U1/walk/p018_22_05.jpg","say":"오른쪽 사진. 정원을 낀 낮은 독립주택들이 줄지어 있어요."}]}},{"p":19,"title":"심미주의 운동과 고딕의 부활","terms":["존 러스킨","어거스트 퓨진","고딕 리바이벌","길드","산업혁명"],"pass1":[{"kind":"say","lines":["이 쪽부터 이야기가 '기계가 싫다' 로 넘어가요.","**존 러스킨(John Ruskin)** 은 기계로 찍은 물건에 영혼이 없다고 화를 낸 잔소리꾼 아저씨예요.","해결책은 하나, 중세 수공예로 돌아가자는 **고딕 리바이벌(Gothic Revival)** 이에요."]},{"kind":"analogy","head":"잔소리꾼 러스킨 아저씨","scene":"공장에서 똑같이 찍어 낸 물건을 보고 '이건 정직하지 않다' 고 매번 야단을 쳐요.","map":[["공장에서 찍은 물건","**산업혁명(Industrial Revolution)** 의 대량생산"],["손으로 만든 물건","중세적 수공예"],["돌아가자고 가리킨 시대","중세 고딕"]]}],"pass2":[{"kind":"points","head":"**존 러스킨(John Ruskin)** 의 주장","items":["영국의 평론가로 1819년에 태어나 1900년에 세상을 떠났어요.","복고주의자들과 함께 중세의 고딕양식으로 돌아갈 것을 주장했어요. 이것이 **고딕 리바이벌(Gothic Revival)** 이에요.","중세 건축의 질에 주의를 기울이고 중세적 수공예를 찬양했어요.","기계에 의한 대량생산에서 오는 품질 저하에 반발했어요.","공업적으로 생산된 물건의 몰개성적 디자인을 통렬하게 비난했어요.","고칠 유일한 방법은 수공예로 돌아가는 것이라고 강조했어요."]},{"kind":"points","head":"정직성과 **길드(Guild)**","items":["기능, 재료, 생산 기술을 표현해 내는 데 있어서의 정직성을 중요하게 여겼어요.","1871년 **길드(Guild)** 를 결성해 재료에 대한 정직성과 수공예를 강조했어요.","이 **길드(Guild)** 는 많은 예술가와 건축가에게 큰 영향을 끼쳤어요.","같은 흐름의 또 한 사람이 **어거스트 퓨진(Augustus Pugin)**, 1812년에서 1852년이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1871년에 결성되어 재료에 대한 정직성과 수공예를 강조한 조직은 무엇일까요?","choices":["**길드(Guild)**","독일공작연맹","분리파"],"a":0,"why":"1871년 길드예요. 독일공작연맹은 4강에 나오는 다른 조직이에요."},{"kind":"warn","head":"두 사람 구별","items":["**존 러스킨(John Ruskin)** 은 1819년에서 1900년, **어거스트 퓨진(Augustus Pugin)** 은 1812년에서 1852년이에요.","퓨진이 먼저 태어나고 먼저 떠났어요. 러스킨이 더 오래 살았어요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.045,0.38,0.05],"c":[0.031,0.015,0.418,0.11],"r":5.0667,"img":"img/U1/walk/p019_22_01.jpg","say":"제목 '심미주의 운동과 고딕의 부활'."},{"b":[0.5,0.1,0.19,0.38],"c":[0.488,0.081,0.214,0.418],"r":0.6826,"img":"img/U1/walk/p019_22_02.jpg","say":"왼쪽 초상이 **어거스트 퓨진(Augustus Pugin)**, 1812에서 1852."},{"b":[0.72,0.1,0.2,0.38],"c":[0.708,0.081,0.224,0.418],"r":0.7145,"img":"img/U1/walk/p019_22_03.jpg","say":"오른쪽 초상이 **존 러스킨(John Ruskin)**, 1819에서 1900."},{"b":[0.07,0.5,0.88,0.2],"c":[0.026,0.484,0.968,0.232],"r":5.5632,"img":"img/U1/walk/p019_22_04.jpg","say":"첫 두 줄. 중세 고딕으로 돌아가자는 주장이에요."},{"b":[0.07,0.68,0.88,0.14],"c":[0.026,0.6522,0.968,0.1956],"r":6.5985,"img":"img/U1/walk/p019_22_05.jpg","say":"러스킨의 통렬한 비난과 수공예로 돌아가라는 결론이에요."},{"b":[0.08,0.85,0.7,0.1],"c":[0.045,0.8222,0.77,0.1556],"r":6.5981,"img":"img/U1/walk/p019_22_06.jpg","say":"1871년 **길드(Guild)** 결성 줄이에요."}]}},{"p":20,"title":"영국의 고딕 리바이벌과 기독교 사회주의","terms":["고딕 리바이벌","빅토리안 고딕","기독교 사회주의","Arts and Crafts Movement","존 러스킨","어거스트 퓨진","산업혁명"],"pass1":[{"kind":"say","lines":["같은 '중세로 돌아가자' 인데 나라마다 방식이 달랐다는 쪽이에요.","영국은 가장 늦게까지 고딕을 붙잡았고 그 별칭이 **빅토리안 고딕(Victorian Gothic)** 이에요.","이 운동에는 종교와 사회 색깔도 있어서 **기독교 사회주의(Christian Socialism)** 라고도 불러요."]},{"kind":"compare","head":"나라마다 다른 중세 되살리기","cols":["나라","무엇을 되살렸나"],"rows":[["프랑스","자국 고딕의 구조 합리주의를 철물 건축에 적용"],["독일","로마네스크 리바이벌과 비더마이어 양식"],["영국","**미술공예운동(Arts and Crafts Movement)**, 퀸 앤 리바이벌, 올드 잉글리시 스타일, **빅토리안 고딕(Victorian Gothic)**"]]}],"pass2":[{"kind":"points","head":"영국의 **고딕 리바이벌(Gothic Revival)**","items":["고딕의 종주국이라는 자부심이 있었어요.","유럽 여러 나라 중 가장 늦게까지 고딕양식을 지속했어요. 18세기까지예요.","그래서 영국의 **고딕 리바이벌(Gothic Revival)** 에는 **빅토리안 고딕(Victorian Gothic)** 이라는 별칭이 붙어요."]},{"kind":"points","head":"중세주의와 고딕의 부활","items":["**고딕 리바이벌(Gothic Revival)** 을 포함해 중세 문명 전반을 되살리는 포괄적 문명운동이 나타났어요.","영국은 **산업혁명(Industrial Revolution)** 의 폐해에 대한 대안 운동으로 중세 정신에 기대는 경향이 있었어요."]},{"kind":"points","head":"**기독교 사회주의(Christian Socialism)**","items":["**어거스트 퓨진(Augustus Pugin)** 과 **존 러스킨(John Ruskin)** 이 이끈 건축 운동이에요.","정신적, 사회적 문제가 극에 달한 자본주의의 폐해에 대한 대안 운동으로 등장했어요.","중세 가톨릭 부활에 사회주의를 결합한 운동이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"영국의 **고딕 리바이벌(Gothic Revival)** 에 붙은 별칭은 무엇일까요?","choices":["로마네스크 리바이벌","**빅토리안 고딕(Victorian Gothic)**","비더마이어 양식"],"a":1,"why":"로마네스크 리바이벌과 비더마이어는 독일이에요. 나라를 바꿔 묻는 문제가 나와요."},{"kind":"english","head":"논술 답안: 기독교 사회주의","en":"기독교 사회주의는 퓨진과 러스킨이 이끈 건축 운동으로, 정신적 사회적 문제가 극에 달한 자본주의의 폐해에 대한 대안으로 등장하였으며, 중세 가톨릭의 부활에 사회주의를 결합한 운동이다.","ko":"누가, 왜, 무엇을 결합했는지 세 마디로 써요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.1,0.92,0.16],"c":[0,0.0778,1,0.2045],"r":6.52,"img":"img/U1/walk/p020_23_01.jpg","say":"위 덩어리. 영국이 가장 늦게까지 고딕을 지속했다는 말이에요."},{"b":[0.05,0.35,0.92,0.33],"c":[0,0.3335,1,0.363],"r":3.6731,"img":"img/U1/walk/p020_23_02.jpg","say":"가운데 덩어리. 프랑스, 독일, 영국을 갈라 읽어요."},{"b":[0.07,0.72,0.92,0.24],"c":[0,0.704,1,0.272],"r":4.902,"img":"img/U1/walk/p020_23_03.jpg","say":"아래 덩어리가 **기독교 사회주의(Christian Socialism)** 예요."}]}},{"p":21,"title":"미술공예운동: Arts and Craft","terms":["Arts and Crafts Movement","존 러스킨","어거스트 퓨진","산업혁명"],"pass1":[{"kind":"say","lines":["드디어 1강의 주인공, **미술공예운동(Arts and Crafts Movement)** 이에요.","**어거스트 퓨진(Augustus Pugin)** 과 **존 러스킨(John Ruskin)** 의 철학이 배경이에요.","핵심은 손으로 만드는 즐거움을 되찾자는 것이에요."]},{"kind":"compare","head":"**산업혁명(Industrial Revolution)** 앞과 뒤","cols":["언제","누가 디자인했나"],"rows":[["산업혁명 이전","장인이 도제시절을 거쳐 배우고, 의뢰인의 물품을 그 시대 미감에 맞게 디자인해 제작"],["산업혁명 이후","노동자는 기계로 조립만 하고, 디자인은 오너와 매니저가 유행을 따라 결정"]]}],"pass2":[{"kind":"points","head":"**미술공예운동(Arts and Crafts Movement)** 의 배경과 주장","items":["빅토리아 시대 **어거스트 퓨진(Augustus Pugin)**, **존 러스킨(John Ruskin)** 의 철학이 그 배경이 됐어요.","19세기 산업화의 우울한 분위기에서 벗어나려 했어요.","아름다운 건축재료를 썼어요. 공업화에 대한 반기이고, 수공예로부터 느끼는 즐거움을 강조했어요."]},{"kind":"points","head":"이름과 자리","items":["1888년 11월 런던에서 전시회를 열면서 'Arts and Crafts Exhibition Society' 라는 단체 이름을 처음 썼어요.","아트 앤 크래프트 운동은 그 시대의 독창적인 디자인을 추구했어요. 디자이너가 디자인에 끼어들기 시작한 것이에요.","그래서 '모던' 의 시초로 쳐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'Arts and Crafts Exhibition Society' 라는 이름이 처음 쓰인 때는 언제일까요?","choices":["1860년","1888년 11월 런던 전시회","1900년 파리 박람회"],"a":1,"why":"1888년 11월 런던 전시회예요."},{"kind":"warn","head":"연도 두 가지","items":["**미술공예운동(Arts and Crafts Movement)** 양식의 시기는 1860년에서 1900년으로 적혀 있어요.","다만 다음 쪽 모리스 설명에는 1860년에서 1925년으로 적혀 있어요. 슬라이드에 두 표기가 같이 있으니 둘 다 알아 둬요."]},{"kind":"english","head":"논술 답안: 미술공예운동","en":"미술공예운동은 퓨진과 러스킨의 철학을 배경으로 19세기 산업화의 우울한 분위기에서 벗어나고자 한 운동으로, 공업화에 반기를 들고 수공예의 즐거움을 강조하였으며, 1888년 런던 전시회에서 그 이름이 처음 사용되었다.","ko":"배경, 주장, 이름의 유래 세 덩어리로 써요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.42,0.06],"c":[0.019,0.025,0.462,0.11],"r":5.6,"img":"img/U1/walk/p021_22_01.jpg","say":"제목 '미술공예 운동 : Arts and Craft'."},{"b":[0.04,0.16,0.92,0.23],"c":[0.0,0.144,1,0.262],"r":5.0891,"img":"img/U1/walk/p021_22_02.jpg","say":"배경과 주장. 퓨진과 러스킨 이름을 찾아 읽어요."},{"b":[0.04,0.4,0.92,0.19],"c":[0.0,0.384,1,0.222],"r":6.006,"img":"img/U1/walk/p021_22_03.jpg","say":"**산업혁명(Industrial Revolution)** 이전과 이후를 견주는 두 줄이에요."},{"b":[0.04,0.61,0.92,0.12],"c":[0.0,0.5678,1,0.2045],"r":6.52,"img":"img/U1/walk/p021_22_04.jpg","say":"1888년 11월 런던 전시회, 단체 이름이 처음 쓰인 자리예요."},{"b":[0.04,0.75,0.6,0.11],"c":[0.01,0.734,0.66,0.142],"r":6.1972,"img":"img/U1/walk/p021_22_05.jpg","say":"마지막 두 줄. 디자이너의 개입, '모던' 의 시초예요."}]}},{"p":22,"title":"미술공예운동 양식(1860~1900)과 윌리엄 모리스","terms":["Arts and Crafts Movement","William Morris","모리스 마샬 포크너","Red House"],"pass1":[{"kind":"say","lines":["**미술공예운동(Arts and Crafts Movement)** 을 실제로 이끈 사람이에요.","**윌리엄 모리스(William Morris)**, 1834년에서 1896년이에요.","벽지와 직물 무늬로 유명한 디자이너이자 회사 사장이에요."]},{"kind":"analogy","head":"자연을 그대로 옮긴 벽지 가게","scene":"모리스의 무늬에는 늘 식물, 꽃, 새가 나와요. 자연을 존경했기 때문이에요.","map":[["가게 이름","**모리스 마샬 포크너(Morris, Marshall, Faulkner and Co.)**"],["파는 물건","태피스트리, 벽지, 가구, 스테인드글라스"],["무늬의 소재","식물, 꽃, 새"]]}],"pass2":[{"kind":"points","head":"**윌리엄 모리스(William Morris)** 가 한 일","items":["1859년에서 1860년에 **붉은 집(Red House)** 을 디자인했어요.","1861년에 **모리스 마샬 포크너(Morris, Marshall, Faulkner and Co.)** 라는 회사를 세웠어요.","그 회사에서 태피스트리와 벽지, 가구, 스테인드글라스 등을 생산했어요.","직물과 벽지, 책, 활판 인쇄를 위한 2차원적 디자인에 초점을 맞췄어요.","직물 디자인은 항상 자연의 모티프에 근거했고, 식물, 꽃, 새 같은 소재에 큰 존경심을 보였어요."]},{"kind":"points","head":"정리 세 줄","items":["재료에 대한 정직과 수공예 정신을 계승했어요.","**미술공예운동(Arts and Crafts Movement)** (1860에서 1925)을 주도했어요.","수공예정신에 입각한 장식품 등을 제작했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**윌리엄 모리스(William Morris)** 가 1861년에 세운 회사 이름은 무엇일까요?","choices":["**모리스 마샬 포크너(Morris, Marshall, Faulkner and Co.)**","모리스 앤 웹","아트 앤 크래프트 소사이어티"],"a":0,"why":"1861년 모리스 마샬 포크너예요. 벽지, 직물, 가구, 스테인드글라스를 만들었어요."},{"kind":"english","head":"논술 답안: 윌리엄 모리스","en":"윌리엄 모리스는 1861년 모리스 마샬 포크너를 설립하여 태피스트리와 벽지, 가구, 스테인드글라스를 생산하였고, 자연의 식물과 꽃과 새를 모티프로 한 2차원 디자인에 집중하였으며, 재료에 대한 정직과 수공예 정신으로 미술공예운동을 주도하였다.","ko":"회사, 물건, 무늬, 정신 네 가지를 넣어요.","tip":"'1861 회사, 1859 붉은 집' 두 해를 짝으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.43,0.06],"c":[0.0185,0.035,0.473,0.11],"r":5.7333,"img":"img/U1/walk/p022_22_01.jpg","say":"제목에 양식의 시기 1860에서 1900이 들어 있어요."},{"b":[0.73,0.03,0.21,0.33],"c":[0.718,0.0135,0.234,0.363],"r":0.8595,"img":"img/U1/walk/p022_22_02.jpg","say":"오른쪽 사진이 **윌리엄 모리스(William Morris)** 예요."},{"b":[0.06,0.27,0.46,0.05],"c":[0.037,0.24,0.506,0.11],"r":6.1333,"img":"img/U1/walk/p022_22_03.jpg","say":"이름과 생몰년 1834에서 1896이 적혀 있어요."},{"b":[0.06,0.38,0.85,0.32],"c":[0.0175,0.364,0.935,0.352],"r":3.5417,"img":"img/U1/walk/p022_22_04.jpg","say":"회사 설립 1861년과 만든 물건 목록이에요."},{"b":[0.06,0.74,0.5,0.17],"c":[0.035,0.724,0.55,0.202],"r":3.6304,"img":"img/U1/walk/p022_22_05.jpg","say":"마지막 세 줄이 정리예요."}]}},{"p":23,"title":"붉은 집(Red House), 1859","terms":["Red House","필립 웹","William Morris"],"pass1":[{"kind":"say","lines":["**미술공예운동(Arts and Crafts Movement)** 이 집으로 나타난 것이 **붉은 집(Red House)** 이에요.","1859년 런던 근교에 **윌리엄 모리스(William Morris)** 를 위해 지었어요.","설계는 **필립 웹(Philip Webb)** 과 **윌리엄 모리스(William Morris)** 예요."]},{"kind":"points","head":"한 줄로 외울 것","items":["**붉은 집(Red House)** 은 현대 주택의 효시예요.","영국의 소주택과 농가주택에 기초한 단순한 토속미를 강조했어요."]}],"pass2":[{"kind":"points","head":"**붉은 집(Red House)** 의 네 가지 특징","items":["1859년 런던 근교에 **윌리엄 모리스(William Morris)** 를 위해 지었어요.","**필립 웹(Philip Webb)** 과 **윌리엄 모리스(William Morris)** 가 함께 설계했어요.","영국의 소주택과 농가주택에 기초한 좀 더 단순한 토속미를 강조했어요.","현대 주택의 효시로 꼽혀요.","불규칙한 평면을 가져요. 기능에 따른 자유로운 공간구성이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽 사진은 외관이에요. 붉은 벽돌을 칠하지 않고 그대로 드러냈어요.","지붕이 여러 방향으로 꺾여 있어요. 방을 기능대로 배치하다 보니 평면이 불규칙해졌기 때문이에요.","오른쪽 사진은 실내예요. 나무 마감과 벽돌 벽난로가 그대로 보여요.","캡션에 '필립 웹과 모리스, Red House, 영국 벡슬리 히스, 1865' 라고 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**붉은 집(Red House)** 을 설계한 사람은 누구일까요?","choices":["존 러스킨과 퓨진","**필립 웹(Philip Webb)** 과 **윌리엄 모리스(William Morris)**","언윈과 파커"],"a":1,"why":"필립 웹과 모리스예요. 러스킨은 이론가이지 이 집의 설계자가 아니에요."},{"kind":"warn","head":"연도가 두 개인 이유","items":["본문에는 1859년 건축, 캡션에는 1865년이라고 적혀 있어요.","시작한 해와 사진 설명의 연도가 달라요. 슬라이드에 적힌 그대로 둘 다 기억해 두면 안전해요."]},{"kind":"english","head":"논술 답안: 붉은 집","en":"붉은 집은 1859년 런던 근교에 윌리엄 모리스를 위해 필립 웹과 모리스가 설계한 주택으로, 영국의 소주택과 농가주택에 기초한 단순한 토속미를 강조하고 기능에 따른 자유로운 불규칙 평면을 가져 현대 주택의 효시로 평가된다.","ko":"연도, 설계자, 토속미, 불규칙 평면, 효시 다섯을 넣어요.","tip":"'붉은 벽돌, 붉은 집, 현대 주택의 효시' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.035,0.16,0.05],"c":[0.04,0.005,0.2,0.11],"r":2.4242,"img":"img/U1/walk/p023_22_01.jpg","say":"제목 '붉은 집(Red House)'."},{"b":[0.09,0.1,0.78,0.09],"c":[0.051,0.0583,0.858,0.1733],"r":6.6013,"img":"img/U1/walk/p023_22_02.jpg","say":"첫 줄에 1859년, 런던 근교, 설계자 두 사람이 다 있어요."},{"b":[0.09,0.2,0.55,0.18],"c":[0.0625,0.184,0.605,0.212],"r":3.805,"img":"img/U1/walk/p023_22_03.jpg","say":"토속미, 현대 주택의 효시, 불규칙한 평면 세 줄이에요."},{"b":[0.09,0.44,0.46,0.5],"c":[0.067,0.415,0.506,0.55],"r":1.2267,"img":"img/U1/walk/p023_22_04.jpg","say":"왼쪽 사진. 붉은 벽돌 외관과 꺾인 지붕을 봐요."},{"b":[0.59,0.44,0.35,0.5],"c":[0.5725,0.415,0.385,0.55],"r":0.9333,"img":"img/U1/walk/p023_22_05.jpg","say":"오른쪽 사진. 나무와 벽돌을 그대로 쓴 실내예요."},{"b":[0.11,0.955,0.44,0.03],"c":[0.088,0.89,0.484,0.11],"r":5.8667,"img":"img/U1/walk/p023_22_06.jpg","say":"캡션의 도시 이름 벡슬리 히스를 기억해요."}]}},{"p":24,"title":"붉은 집의 평면과 실내","terms":["Red House","필립 웹","William Morris"],"pass1":[{"kind":"say","lines":["**붉은 집(Red House)** 의 평면도와 실내 사진을 보는 쪽이에요.","왼쪽 글 네 줄이 이 집의 성격을 그대로 말해 줘요.","기능적으로 연결된 공간, 안팎이 하나인 평면, 성실한 재료, 소극적인 외관이에요."]}],"pass2":[{"kind":"points","head":"슬라이드의 네 줄 그대로","items":["기능적으로 연결된 각각의 공간이에요.","내부와 외부가 일체화된 평면이에요.","성실한 재료 사용이에요. 재료를 감추지 않고 그대로 쓴다는 뜻이에요.","소극적인 외관이에요. 겉을 화려하게 꾸미지 않는다는 뜻이에요."]},{"kind":"points","head":"평면도에서 볼 것","items":["위가 1층(GROUND FLOOR), 아래가 2층(SECOND FLOOR)이에요.","1층에 KITCHEN, DINING ROOM, ENTRY HALL, WAITING ROOM 이 적혀 있어요.","2층에 BEDROOM 여러 개와 DRAWING ROOM, STUDY 가 적혀 있어요.","전체 모양이 직사각형이 아니라 L 자로 꺾여 있어요. 이것이 불규칙한 평면이에요.","방을 먼저 줄 세우지 않고 쓰임새대로 놓은 뒤 모양이 따라온 것이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**붉은 집(Red House)** 의 평면이 불규칙한 이유는 무엇일까요?","choices":["땅이 좁아서","기능에 따라 공간을 자유롭게 구성했기 때문","구조가 약해서"],"a":1,"why":"기능에 따른 자유로운 공간구성이 먼저이고 모양은 그 결과예요."}],"walk":{"head":null,"parts":[{"b":[0.08,0.09,0.36,0.25],"c":[0.062,0.074,0.396,0.282],"r":1.8723,"img":"img/U1/walk/p024_22_01.jpg","say":"왼쪽 네 줄. 이 집의 성격 요약이에요."},{"b":[0.06,0.35,0.37,0.61],"c":[0.0415,0.3195,0.407,0.671],"r":0.8087,"img":"img/U1/walk/p024_22_02.jpg","say":"평면도. 위가 1층, 아래가 2층이에요."},{"b":[0.13,0.37,0.28,0.16],"c":[0.116,0.354,0.308,0.192],"r":2.1389,"img":"img/U1/walk/p024_22_03.jpg","say":"1층의 KITCHEN 과 DINING ROOM 이 나란히 붙어 있어요."},{"b":[0.49,0.04,0.48,0.44],"c":[0.466,0.018,0.528,0.484],"r":1.4545,"img":"img/U1/walk/p024_22_04.jpg","say":"오른쪽 위 사진. 나무 천장과 붙박이 가구가 보여요."},{"b":[0.49,0.49,0.48,0.45],"c":[0.466,0.4675,0.528,0.495],"r":1.4222,"img":"img/U1/walk/p024_22_05.jpg","say":"오른쪽 아래 사진. 크고 붉은 벽돌 벽난로가 주인공이에요."},{"b":[0.52,0.955,0.42,0.03],"c":[0.499,0.89,0.462,0.11],"r":5.6,"img":"img/U1/walk/p024_22_06.jpg","say":"캡션: 필립 웹과 모리스, Red House, 영국 벡슬리 히스, 1865."}]}},{"p":25,"title":"붉은 집의 실내 두 장면","terms":["Red House","William Morris","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["사진 두 장뿐인 쪽이에요. 앞 쪽에 이어 **붉은 집(Red House)** 실내예요.","화려한 장식 대신 나무와 타일과 벽돌이 그대로 보여요.","이것이 **미술공예운동(Arts and Crafts Movement)** 이 말하는 '재료에 대한 정직' 이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽은 벽난로가 있는 방이에요. 벽난로 둘레를 손으로 그린 타일로 둘렀어요.","천장의 나무 보와 받침목을 감추지 않고 그대로 드러냈어요.","오른쪽은 등받이가 높은 의자와 나무 벽판, 붙박이 선반이 있는 방이에요.","천장에 매단 등도 나무와 종이로 만든 수공예품이에요.","가구와 조명과 벽을 한 사람이 함께 디자인한 점이 **윌리엄 모리스(William Morris)** 방식이에요.","캡션은 앞 쪽과 같아요. 필립 웹과 모리스, Red House, 영국 벡슬리 히스, 1865."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.04,0.39,0.45,0.51],"c":[0.0175,0.3645,0.495,0.561],"r":1.1765,"img":"img/U1/walk/p025_21_01.jpg","say":"왼쪽 사진. 타일로 두른 벽난로와 드러난 나무 보예요."},{"b":[0.51,0.08,0.47,0.84],"c":[0.483,0.038,0.517,0.924],"r":0.746,"img":"img/U1/walk/p025_21_02.jpg","say":"오른쪽 사진. 등받이가 높은 의자와 나무 벽판이에요."},{"b":[0.63,0.09,0.2,0.16],"c":[0.618,0.074,0.224,0.192],"r":1.5556,"img":"img/U1/walk/p025_21_03.jpg","say":"천장에 매단 수공예 등이에요."},{"b":[0.52,0.945,0.42,0.03],"c":[0.499,0.89,0.462,0.11],"r":5.6,"img":"img/U1/walk/p025_21_04.jpg","say":"캡션: 필립 웹과 모리스, Red House, 영국 벡슬리 히스, 1865."}]}},{"p":26,"title":"미술공예운동의 한계와 벽지","terms":["Arts and Crafts Movement","William Morris","모리스 마샬 포크너"],"pass1":[{"kind":"say","lines":["좋은 운동이었지만 왜 오래 못 갔는지 말하는 쪽이에요.","손으로 만드니까 값이 비싸서 보통 사람은 살 수 없었어요.","그래도 아르누보 같은 뒤의 운동에 큰 영향을 남겼어요."]},{"kind":"analogy","head":"비싼 수제 빵집","scene":"손으로 반죽한 빵은 맛있지만 공장 빵보다 훨씬 비싸요. 그래서 동네 사람 모두가 사 먹지는 못해요.","map":[["손으로 만든 비싼 빵","수공예 소량 생산"],["공장에서 찍은 싼 빵","기계 생산"],["결국 문을 닫음","**미술공예운동(Arts and Crafts Movement)** 의 한계"]]}],"pass2":[{"kind":"points","head":"**미술공예운동(Arts and Crafts Movement)** 의 한계","items":["수공예로 소량 생산하니 기계 생산보다 값이 비쌌어요.","그래서 일반대중의 수요를 충족시키지 못했어요.","수공예에 의한 생산은 비용이 많이 들고 산업화에 역행하는 것이었어요.","시대에 역행하면서 기계에 반발했어요.","그럼에도 아르누보 등 현대예술운동에 많은 영향을 끼쳤어요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽 아래 세 장이 미술공예양식의 벽지예요. 식물과 꽃과 새 무늬가 촘촘히 반복돼요.","무늬가 좌우 대칭으로 짜여 있어서 벽에 이어 붙여도 이음새가 눈에 안 띄어요.","오른쪽은 **모리스 마샬 포크너(Morris, Marshall, Faulkner and Co.)** 의 뒤를 이은 모리스 상회의 의자 광고예요.","광고 제목에 THE SUSSEX RUSH-SEATED CHAIRS, MORRIS AND COMPANY 라고 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**미술공예운동(Arts and Crafts Movement)** 의 가장 큰 한계는 무엇일까요?","choices":["기술이 부족했다","수공예 소량 생산이라 값이 비싸 대중이 살 수 없었다","재료를 구할 수 없었다"],"a":1,"why":"비싸서 대중의 수요를 못 채운 것이 한계예요."},{"kind":"english","head":"논술 답안: 미술공예운동의 한계","en":"미술공예운동은 수공예에 의한 소량 생산이어서 기계 생산보다 값이 비싸 일반 대중의 수요를 충족시키지 못하였고 산업화에 역행하였으나, 아르누보를 비롯한 현대예술운동에 큰 영향을 끼쳤다.","ko":"한계 두 가지와 그래도 남긴 영향을 함께 써요.","tip":"'비싸서 실패, 그래도 아르누보의 엄마' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.09,0.9,0.16],"c":[0.005,0.07,0.99,0.2],"r":6.6,"img":"img/U1/walk/p026_22_01.jpg","say":"위 덩어리가 한계예요. 비싸다, 대중이 못 산다가 핵심이에요."},{"b":[0.06,0.26,0.55,0.11],"c":[0.0325,0.244,0.605,0.142],"r":5.6808,"img":"img/U1/walk/p026_22_02.jpg","say":"마지막 줄. 아르누보에 영향을 주었다는 연결고리예요."},{"b":[0.005,0.5,0.56,0.42],"c":[0,0.479,0.616,0.462],"r":1.7778,"img":"img/U1/walk/p026_22_03.jpg","say":"벽지 석 장. 식물, 꽃, 새 무늬를 확인해요."},{"b":[0.62,0.45,0.36,0.5],"c":[0.602,0.425,0.396,0.55],"r":0.96,"img":"img/U1/walk/p026_22_04.jpg","say":"오른쪽 의자 광고. 수공예 정신으로 만든 생활용품이에요."}]}},{"p":27,"title":"근대적 주거에 대한 요구, 근대주택의 태동기","terms":["현대주택의 계획 원리"],"pass1":[{"kind":"say","lines":["사람들이 집에 새로운 것을 요구하기 시작한 쪽이에요.","프라이버시, 여유, 안락함, 편리함이에요.","건축가 스티븐슨이 그 요구를 세 가지 원리로 정리했어요."]},{"kind":"points","head":"세 가지 원리만 먼저","items":["방마다 기능을 나눈다.","계단과 복도를 줄인다.","부엌과 식당을 가깝게 둔다."]}],"pass2":[{"kind":"points","head":"주택 외관의 다양화","items":["주택의 공간 구성에 대한 다양한 요구가 등장했어요.","프라이버시와 공간적 여유, 안락함과 편리함을 추구했어요.","기능성을 중요하게 보는 평면구성이 나왔어요."]},{"kind":"points","head":"스티븐슨(J. J. Stevenson)의 **현대주택의 계획 원리(Principles of Modern House Planning)**","items":["각 공간의 명확한 기능적 구분과 공간적 분리예요.","계단실 및 통로 면적의 최소화예요.","부엌과 식당을 연결하는 동선의 최소화예요.","이 세 가지가 **현대주택의 계획 원리(Principles of Modern House Planning)** 의 전부예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**현대주택의 계획 원리(Principles of Modern House Planning)** 에 들어가지 않는 것은?","choices":["각 공간의 기능적 구분","계단실과 통로 면적의 최소화","외관의 장식 강화"],"a":2,"why":"장식 이야기는 없어요. 기능 구분, 통로 최소화, 부엌과 식당 동선 최소화 세 가지예요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.12,0.58,0.05],"c":[0.011,0.0806,0.638,0.1289],"r":6.5994,"img":"img/U1/walk/p027_22_01.jpg","say":"제목 '근대적 주거에 대한 요구, 근대주택의 태동기'."},{"b":[0.07,0.23,0.55,0.22],"c":[0.0425,0.214,0.605,0.252],"r":3.2011,"img":"img/U1/walk/p027_22_02.jpg","say":"위 덩어리가 주택 외관의 다양화예요."},{"b":[0.07,0.53,0.65,0.05],"c":[0.0375,0.4828,0.715,0.1445],"r":6.5975,"img":"img/U1/walk/p027_22_03.jpg","say":"스티븐슨과 책 이름이 적힌 줄이에요."},{"b":[0.07,0.58,0.55,0.19],"c":[0.0425,0.564,0.605,0.222],"r":3.6336,"img":"img/U1/walk/p027_22_04.jpg","say":"그 아래 세 줄이 계획 원리 세 가지예요."}]}},{"p":28,"title":"C. F. A. 보이지, 브로들리 주택, 1898","terms":["C. F. A. 보이지","Broadleys"],"pass1":[{"kind":"say","lines":["사람 하나와 집 하나가 나오는 쪽이에요.","**C. F. A. 보이지(C. F. A. Voysey)**, 1857년에서 1941년이에요.","작품은 전원 주택 **브로들리(Broadleys)**, 1898년이에요."]},{"kind":"analogy","head":"호수를 보는 세 개의 둥근 창","scene":"집 앞이 호수예요. 경치를 잘 보라고 벽을 둥글게 내밀고 창을 크게 냈어요.","map":[["둥글게 내민 벽","조각된 휘어진 창문"],["창이 바라보는 곳","호수"],["창의 개수","세 개"]]}],"pass2":[{"kind":"points","head":"**C. F. A. 보이지(C. F. A. Voysey)** 와 **브로들리(Broadleys)**","items":["전원 주택인 **브로들리(Broadleys)** 를 1898년에 디자인했어요.","호수 쪽을 바라보는 세 개의 조각된 휘어진 창문이 있어요.","인테리어는 공예지향에 근거한 솔직함이 있어요.","실내 공간은 굉장히 단순하고 우아해요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["사진에서 벽면이 둥글게 튀어나온 부분이 셋 보여요. 그것이 휘어진 창문이에요.","벽은 흰색으로 칠했고, 지붕은 낮고 길게 덮여 있어요.","장식이 거의 없어요. 창과 굴뚝이 형태를 만들어요.","오른쪽은 평면도예요. 거실과 부엌 글자가 보이고, 아래에 VERANDA 가 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**브로들리(Broadleys)** 주택에서 호수를 바라보는 휘어진 창문은 몇 개일까요?","choices":["한 개","두 개","세 개"],"a":2,"why":"세 개의 조각된 휘어진 창문이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.83,0.04],"c":[0.0085,0,0.913,0.1845],"r":6.598,"img":"img/U1/walk/p028_22_01.jpg","say":"맨 윗줄이 이름과 생몰년이에요. 1857에서 1941."},{"b":[0.06,0.14,0.62,0.22],"c":[0.029,0.124,0.682,0.252],"r":3.6085,"img":"img/U1/walk/p028_22_02.jpg","say":"네 줄 설명. 1898, 휘어진 창문 세 개를 봐요."},{"b":[0.02,0.54,0.49,0.39],"c":[0,0.5205,0.539,0.429],"r":1.6752,"img":"img/U1/walk/p028_22_03.jpg","say":"왼쪽 사진. 둥글게 내민 창 세 곳을 찾아봐요."},{"b":[0.52,0.57,0.39,0.35],"c":[0.5005,0.5525,0.429,0.385],"r":1.4857,"img":"img/U1/walk/p028_22_04.jpg","say":"오른쪽 평면도. 거실이 호수 쪽으로 붙어 있어요."},{"b":[0.63,0.945,0.29,0.03],"c":[0.6155,0.89,0.319,0.11],"r":3.8667,"img":"img/U1/walk/p028_22_05.jpg","say":"캡션: C. F. A. 보이지, 브로들리주택, 1898."}]}},{"p":29,"title":"C. F. A. 보이지, 오챠드, 1900","terms":["C. F. A. 보이지","오챠드","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["**C. F. A. 보이지(C. F. A. Voysey)** 자신의 집, **오챠드(The Orchard)** 예요.","1900년, 잉글랜드 허트포드셔의 촐리 우드에 있어요.","이 거실이 다음 세기 모더니즘을 미리 보여 준다고 해요."]},{"kind":"points","head":"왜 중요한가요","items":["**미술공예운동(Arts and Crafts Movement)** 의 손맛에서 출발했는데 장식이 거의 없어요.","그래서 20세기 모더니즘의 예고편으로 읽혀요."]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["자신의 주택에 있는 거실 공간에서 작업했어요.","다음 세기에 표현화될 모더니즘의 사상들을 암시하는 단순한 요소들을 갖고 작업했어요.","캡션은 C. F. A. 보이지, **오챠드(The Orchard)**, 촐리 우드, 잉그랜드 허트포드셔, 1900 이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["벽난로 둘레가 네모난 타일로만 덮여 있어요. 조각 장식이 없어요.","벽난로 위 선반이 수평으로 길게 뻗어 벽과 한 몸처럼 보여요.","문과 계단 난간도 곧은 선으로만 되어 있어요.","가구는 다리가 가늘고 단순해요. 이런 단순함이 모더니즘을 암시한다는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**오챠드(The Orchard)** 가 중요한 이유는 무엇일까요?","choices":["장식을 가장 화려하게 했기 때문","다음 세기 모더니즘을 암시하는 단순한 요소를 보여 주기 때문","철골로 지었기 때문"],"a":1,"why":"단순함으로 모더니즘을 미리 보여 준 점이 핵심이에요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.07,0.88,0.09],"c":[0.016,0.0172,0.968,0.1956],"r":6.5985,"img":"img/U1/walk/p029_22_01.jpg","say":"위 한 줄이 이 쪽의 주장 전부예요."},{"b":[0.15,0.19,0.65,0.69],"c":[0.1175,0.1555,0.715,0.759],"r":1.256,"img":"img/U1/walk/p029_22_02.jpg","say":"사진 전체. 장식이 없는 단순한 거실이에요."},{"b":[0.25,0.42,0.22,0.24],"c":[0.238,0.404,0.244,0.272],"r":1.1961,"img":"img/U1/walk/p029_22_03.jpg","say":"네모 타일로만 덮인 벽난로를 봐요."},{"b":[0.19,0.89,0.48,0.03],"c":[0.166,0.85,0.528,0.11],"r":6.4,"img":"img/U1/walk/p029_22_04.jpg","say":"캡션에 연도 1900과 지명이 들어 있어요."}]}},{"p":30,"title":"C. F. A. 보이지, Homestead 주택과 과수원 주택","terms":["C. F. A. 보이지"],"pass1":[{"kind":"say","lines":["사진 세 장짜리 쪽이에요. 모두 **C. F. A. 보이지(C. F. A. Voysey)** 의 집이에요.","왼쪽 위는 Homestead 주택, 1906년이에요.","오른쪽 아래는 과수원 주택, 1899년이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["세 집 모두 벽을 흰색으로 칠했고 표면이 거칠어요.","지붕이 낮게 깔리고 처마가 길게 내밀어져 있어요.","창은 가로로 길고 창틀을 여러 칸으로 나눴어요. 창틀 둘레만 색이 달라요.","굴뚝이 크고 단순한 덩어리로 솟아 있어요.","장식 조각이 거의 없어요. 시골집의 소박함을 그대로 쓴 것이에요.","캡션에 적힌 연도는 Homestead 주택 1906, 과수원 주택 1899 예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"연도 세 개 정리","items":["**C. F. A. 보이지(C. F. A. Voysey)** 의 연도는 **브로들리(Broadleys)** 1898, 과수원 주택 1899, **오챠드(The Orchard)** 1900, Homestead 1906 이에요.","1898, 1899, 1900 이 나란히 붙어 있어서 잘 섞여요. 브로들리가 가장 먼저예요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.04,0.34,0.56],"c":[0.013,0.012,0.374,0.616],"r":0.8095,"img":"img/U1/walk/p030_21_01.jpg","say":"왼쪽 위. Homestead 주택이에요. 처마가 길게 나와 있어요."},{"b":[0.03,0.61,0.31,0.04],"c":[0.0145,0.575,0.341,0.11],"r":4.1333,"img":"img/U1/walk/p030_21_02.jpg","say":"캡션: C. F. A. 보이지, Homestead 주택, 1906."},{"b":[0.38,0.03,0.35,0.57],"c":[0.3625,0.0015,0.385,0.627],"r":0.8187,"img":"img/U1/walk/p030_21_03.jpg","say":"가운데 위 사진. 아치를 그린 현관과 흰 벽이 보여요."},{"b":[0.57,0.6,0.41,0.39],"c":[0.549,0.571,0.451,0.429],"r":1.4017,"img":"img/U1/walk/p030_21_04.jpg","say":"오른쪽 아래. 과수원 주택이에요."},{"b":[0.28,0.955,0.27,0.03],"c":[0.2665,0.89,0.297,0.11],"r":3.6,"img":"img/U1/walk/p030_21_05.jpg","say":"캡션: C. F. A. 보이지, 과수원 주택, 1899."}]}},{"p":31,"title":"C. R. 맥킨토시, 힐하우스, 1904","terms":["찰스 레니 매킨토시","힐하우스","Arts and Crafts Movement"],"pass1":[{"kind":"say","lines":["1강의 마지막 쪽이에요. 사진 두 장뿐이에요.","**찰스 레니 매킨토시(Charles Rennie Mackintosh)** 의 **힐하우스(Hill House)**, 1904년이에요.","매킨토시는 2강 아르누보에서 다시 자세히 나와요."]},{"kind":"points","head":"여기서 잡아 둘 것","items":["이름과 작품과 연도, 이 셋만 기억하면 돼요.","**미술공예운동(Arts and Crafts Movement)** 의 손맛이 곧은 선으로 바뀌는 자리예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽은 나무로 짠 계단과 벽판이에요. 네모난 나무 조각을 계단처럼 층층이 쌓았어요.","곡선 장식이 아니라 사각형과 직선이 반복돼요.","오른쪽은 복도예요. 천장에 네모난 등이 줄지어 달려 있어요.","가구도 등받이가 곧고 높아요. 모두 직선과 사각형이에요.","캡션에 C.R. 맥킨토시, **힐하우스(Hill House)**, 1904 라고 적혀 있어요.","**찰스 레니 매킨토시(Charles Rennie Mackintosh)** 는 곡선의 아르누보 안에서 직선을 쓴 사람이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**힐하우스(Hill House)** 를 설계한 사람과 연도는?","choices":["윌리엄 모리스, 1859","**찰스 레니 매킨토시(Charles Rennie Mackintosh)**, 1904","C. F. A. 보이지, 1898"],"a":1,"why":"맥킨토시의 힐하우스는 1904년이에요."},{"kind":"recap","items":["1강 한 번에 되짚기","**산업혁명(Industrial Revolution)** 으로 철과 유리가 나오고 새 건물 종류가 생겼어요.","**에베네저 하워드(Ebenezer Howard)** 의 **전원도시(Garden City)** 와 **레치워스(Letchworth)** 가 도시의 답이었어요.","**존 러스킨(John Ruskin)** 과 **어거스트 퓨진(Augustus Pugin)** 이 '기계 싫어' 를 외쳤어요.","**윌리엄 모리스(William Morris)** 가 **미술공예운동(Arts and Crafts Movement)** 과 **붉은 집(Red House)** 으로 실천했어요.","주문을 다시 외워요. 싫어 → 새 장식 → 정리 → 없애."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.22,0.51,0.53],"c":[0,0.1935,0.561,0.583],"r":1.283,"img":"img/U1/walk/p031_21_01.jpg","say":"왼쪽 사진. 층층이 쌓인 네모 나무 조각을 봐요."},{"b":[0.55,0.1,0.43,0.8],"c":[0.527,0.06,0.473,0.88],"r":0.7167,"img":"img/U1/walk/p031_21_02.jpg","say":"오른쪽 사진. 네모난 등이 줄지어 달린 복도예요."},{"b":[0.74,0.12,0.2,0.18],"c":[0.728,0.104,0.224,0.212],"r":1.4088,"img":"img/U1/walk/p031_21_03.jpg","say":"천장 등도 사각형이에요."},{"b":[0.04,0.945,0.23,0.03],"c":[0.028,0.89,0.254,0.11],"r":3.0788,"img":"img/U1/walk/p031_21_04.jpg","say":"캡션: C.R. 맥킨토시, 힐하우스, 1904."}]}}]};
